llm_sql:
SELECT d.name
FROM people.student s
JOIN org.department d ON s.department_id = d.department_id;

SELECT COUNT(*) AS not_fully_paid_count
FROM fin.fee_demand
WHERE status <> 'PAID';

SELECT COUNT(*) AS lost_copies
FROM lib.book_copy
WHERE status = 'LOST';

SELECT e.display_name, e.official_email
FROM people.faculty_advisor fa
JOIN people.employee e ON fa.employee_id = e.employee_id;
